"""Software-only scan matching checks. Synthetic scans are generated by independent 5 mm ray marching."""
import math
from pathlib import Path
import sys
import tempfile
import unittest

import numpy as np
from PIL import Image
import yaml

REAL = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(REAL / "scripts"))
from start_scan_match import StartScanMatcher

COURSE_MAP = REAL / "runs/Real_103_2026-11-11_152732/maps/maze_Real_103_2026-11-11_152732.yaml"
LASER = (-.064, .004, .015)
INC = math.pi / 180


def synthetic_scan(path, base, extrinsic, angle_min=0., increment=INC):
    meta = yaml.safe_load(path.read_text())
    with Image.open(path.parent / meta["image"]) as image:
        pixels = np.asarray(image)[::-1]
    ox, oy, map_yaw = meta["origin"]
    x, y, yaw = base
    lx, ly, laser_yaw = extrinsic
    wx = x + lx * math.cos(yaw) - ly * math.sin(yaw) - ox
    wy = y + lx * math.sin(yaw) + ly * math.cos(yaw) - oy
    gx = wx * math.cos(map_yaw) + wy * math.sin(map_yaw)
    gy = -wx * math.sin(map_yaw) + wy * math.cos(map_yaw)
    angles = angle_min + np.arange(360)*increment + yaw + laser_yaw - map_yaw
    steps = np.arange(.005, 3.501, .005)
    ix = np.floor((gx + steps[:, None] * np.cos(angles))/meta["resolution"]).astype(int)
    iy = np.floor((gy + steps[:, None] * np.sin(angles))/meta["resolution"]).astype(int)
    inside = (ix >= 0) & (ix < pixels.shape[1]) & (iy >= 0) & (iy < pixels.shape[0])
    values = np.where(inside, pixels[iy.clip(0, pixels.shape[0]-1), ix.clip(0, pixels.shape[1]-1)], 205)
    first = (values < 250).argmax(axis=0)
    ranges = steps[first]
    return np.where((values[first, np.arange(360)] < 10) & (ranges >= .12), ranges, np.inf)


class StartMatchTest(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.matcher = StartScanMatcher(COURSE_MAP, (0., 0.), LASER)

    def test_home_across_headings_with_outliers(self):
        rng = np.random.default_rng(144)
        for yaw in (0., 1.70, -2.90, -2.40):
            base = (.02, -.01, yaw)
            scan = synthetic_scan(COURSE_MAP, base, LASER, math.pi, -INC)
            hits = np.flatnonzero(np.isfinite(scan))
            scan[hits] += rng.normal(0, .012, len(hits))
            scan[hits[::8]] = np.maximum(.125, .55 * scan[hits[::8]])  # transient nearer returns
            scan[hits[3::11]] = np.nan
            with self.subTest(yaw=yaw):
                result = self.matcher.match(scan, math.pi, -INC, .12, 3.5)
                self.assertTrue(result.accepted, result)
                self.assertLess(math.hypot(result.x-base[0], result.y-base[1]), .075)
                self.assertLess(abs(math.remainder(result.yaw-yaw, math.tau)), math.radians(5))

    def test_global_fit_elsewhere_is_not_home(self):
        base = (1.4, -1.3, 1.9)
        scan = synthetic_scan(COURSE_MAP, base, LASER)
        result = self.matcher.match(scan, 0., INC, .12, 3.5)
        self.assertFalse(result.accepted)
        self.assertIn("outside", result.reason)
        self.assertLess(math.hypot(result.x-base[0], result.y-base[1]), .08)

    def test_uninformative_or_false_scan(self):
        for scan in ([], [np.inf]*360, [.40]*22 + [0.]*338, [.18]*360):
            self.assertFalse(self.matcher.match(scan, 0., INC, .12, 3.5).accepted)

    def test_rotated_map_origin_and_offset_laser(self):
        with tempfile.TemporaryDirectory() as temp:
            path = Path(temp) / "rotated.yaml"
            meta = yaml.safe_load(COURSE_MAP.read_text())
            ox, oy, _ = meta["origin"]
            meta["image"] = str(COURSE_MAP.parent / meta["image"])
            # Re-express the same known start with a distinct world translation and yaw.
            heading = 0.78
            meta["origin"] = [.8, 1.7, heading]
            path.write_text(yaml.safe_dump(meta))
            x = .8 - ox * math.cos(heading) + oy * math.sin(heading)
            y = 1.7 - ox * math.sin(heading) - oy * math.cos(heading)
            base = (x, y, -1.46)
            offset = (-.082, .038, .41)
            matcher = StartScanMatcher(path, base, offset)
            result = matcher.match(synthetic_scan(path, base, offset), 0., INC, .12, 3.5)
            self.assertTrue(result.accepted, result)
            self.assertLess(math.hypot(x - result.x, y - result.y), .045)
            self.assertLess(abs(math.remainder(result.yaw-base[2], math.tau)), math.radians(3))

    def test_equal_pose_or_heading_hypotheses(self):
        with tempfile.TemporaryDirectory() as temp:
            d = Path(temp)
            # Two disconnected copies of a square room with the same wall geometry.
            # The starting location prior must never break their tie.
            img = np.full((58, 115), 205, dtype=np.uint8)
            for x in (2, 60):
                img[2:54, x:x+52] = 0
                img[4:52, x+2:x+50] = 254
            Image.fromarray(img).save(d / "rooms.pgm")
            meta = dict(image="rooms.pgm", resolution=.05, origin=[0., 0., 0.],
                        negate=0, mode="trinary", occupied_thresh=.65, free_thresh=.15)
            path = d / "rooms.yaml"
            path.write_text(yaml.safe_dump(meta))
            for point in ((.9, 1.5, .4), (1.4, 1.5, -1.2)):
                matcher = StartScanMatcher(path, point[:2], LASER)
                result = matcher.match(synthetic_scan(path, point, LASER), 0., INC, .12, 3.5)
                self.assertFalse(result.accepted, result)
                self.assertIn("ambiguous", result.reason)
            # Remove the twin room; rotations of a square still remain ambiguous.
            img[:, 58:] = 205
            Image.fromarray(img).save(d / "rooms.pgm")
            center = (1.4, 1.5, -.66)
            matcher = StartScanMatcher(path, center[:2], (0., 0., 0.))
            result = matcher.match(synthetic_scan(path, center, (0., 0., 0.)), 0., INC, .12, 3.5)
            self.assertFalse(result.accepted, result)
            self.assertIn("ambiguous", result.reason)


if __name__ == "__main__":
    unittest.main()
